      "poi_id": "p154",
      "kind": "activity",
      "must_do_id": null,
      "note": "Làng Pháp nhỏ xinh, đi lạc một vòng là tưởng mình đang ở bên kia địa cầu."
    },
    {
      "poi_id": "p163",
      "kind": "meal",
      "must_do_id": null,
      "note": "Bánh tráng cuốn thịt heo tươi, rau thơm đủ vị, cuốn một cuốn là nhớ hoài."
    }
  ]
}
