    },
    {
      "poi_id": "p208",
      "kind": "activity",
      "must_do_id": null,
      "note": "Chùa Cầu cong cong soi bóng nước, góc nào cũng ra ảnh đẹp."
    },
    {
      "poi_id": "p225",
      "kind": "meal",
      "must_do_id": null,
      "note": "Cơm gà xé tay, rau răm thơm, thêm chút muối tiêu chanh cay nhẹ."
    },
    {
      "poi_id": "p211",
      "kind": "activity",
      "must_do_id": null,
      "note": "Phố cổ lên đèn vàng ấm, mái ngói rêu phong kể chuyện mấy trăm năm."
    },
    {
      "poi_id": "p50",
      "kind": "meal",
      "must_do_id": null,
      "note": "Tacos nóng hổi, vị đậm đà, ngồi lai rai nghe phố đêm rì rào."
    }
  ]
}
```

